import React from 'react';

const Skills: React.FC = () => {
  const skills = [
    { name: 'React', level: 95, icon: '⚛️', color: 'from-blue-500 to-cyan-500' },
    { name: 'TypeScript', level: 90, icon: '📘', color: 'from-blue-600 to-blue-800' },
    { name: 'Node.js', level: 88, icon: '🟢', color: 'from-green-500 to-green-700' },
    { name: 'Python', level: 85, icon: '🐍', color: 'from-yellow-500 to-orange-500' },
    { name: 'SQL', level: 82, icon: '🗄️', color: 'from-purple-500 to-pink-500' },
    { name: 'AWS', level: 80, icon: '☁️', color: 'from-orange-500 to-yellow-500' },
    { name: 'Docker', level: 78, icon: '🐳', color: 'from-blue-500 to-cyan-400' },
    { name: 'Git', level: 92, icon: '📚', color: 'from-orange-600 to-red-600' }
  ];

  const technologies = [
    { name: 'Frontend', items: ['React', 'Vue.js', 'Angular', 'HTML5', 'CSS3', 'Sass'] },
    { name: 'Backend', items: ['Node.js', 'Express', 'Python', 'Django', 'FastAPI', 'PostgreSQL'] },
    { name: 'DevOps', items: ['AWS', 'Docker', 'Kubernetes', 'CI/CD', 'Terraform', 'Monitoring'] },
    { name: 'Tools', items: ['Git', 'VS Code', 'Postman', 'Figma', 'Jira', 'Slack'] }
  ];

  return (
    <section id="skills" className="py-20 bg-dark-bg">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-bold text-text-primary mb-4">
            My <span className="gradient-text">Skills</span>
          </h2>
          <div className="w-24 h-1 bg-accent mx-auto"></div>
          <p className="text-text-secondary mt-6 max-w-2xl mx-auto">
            I've worked with a variety of technologies and frameworks. Here's what I bring to the table.
          </p>
        </div>

        {/* Skills Grid */}
        <div className="grid md:grid-cols-2 gap-8 mb-16">
          {/* Left Column - Skill Bars */}
          <div className="space-y-6">
            <h3 className="text-2xl font-semibold text-text-primary mb-6">
              Technical Proficiency
            </h3>
            {skills.map((skill, index) => (
              <div key={skill.name} className="space-y-2">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <span className="text-2xl">{skill.icon}</span>
                    <span className="text-text-secondary font-medium">{skill.name}</span>
                  </div>
                  <span className="text-accent font-semibold">{skill.level}%</span>
                </div>
                <div className="w-full bg-dark-card rounded-full h-3 overflow-hidden">
                  <div 
                    className={`h-full bg-gradient-to-r ${skill.color} rounded-full transition-all duration-1000 ease-out`}
                    style={{ width: `${skill.level}%` }}
                  ></div>
                </div>
              </div>
            ))}
          </div>

          {/* Right Column - Technology Categories */}
          <div className="space-y-6">
            <h3 className="text-2xl font-semibold text-text-primary mb-6">
              Technology Stack
            </h3>
            {technologies.map((category) => (
              <div key={category.name} className="bg-dark-card border border-dark-border rounded-lg p-6 hover-lift">
                <h4 className="text-lg font-semibold text-accent mb-4">{category.name}</h4>
                <div className="flex flex-wrap gap-2">
                  {category.items.map((item) => (
                    <span 
                      key={item} 
                      className="px-3 py-1 bg-accent/10 text-accent rounded-full text-sm border border-accent/20"
                    >
                      {item}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Additional Skills */}
        <div className="text-center">
          <h3 className="text-2xl font-semibold text-text-primary mb-8">
            What I'm <span className="gradient-text">Learning</span>
          </h3>
          <div className="flex flex-wrap justify-center gap-4">
            {['Machine Learning', 'Blockchain', 'Rust', 'Go', 'GraphQL', 'Microservices'].map((skill) => (
              <div 
                key={skill}
                className="px-6 py-3 bg-dark-card border border-dark-border rounded-lg text-text-secondary hover:text-accent hover:border-accent transition-all duration-300 cursor-pointer"
              >
                {skill}
              </div>
            ))}
          </div>
        </div>

        {/* Experience Timeline */}
        <div className="mt-20">
          <h3 className="text-2xl font-semibold text-text-primary text-center mb-12">
            Experience <span className="gradient-text">Timeline</span>
          </h3>
          <div className="relative">
            {/* Timeline Line */}
            <div className="absolute left-1/2 transform -translate-x-1/2 w-1 h-full bg-accent/20"></div>
            
            {/* Timeline Items */}
            <div className="space-y-12">
              {[
                { year: '2023 - Present', title: 'Senior Full Stack Developer', company: 'TechCorp', description: 'Leading development of enterprise applications' },
                { year: '2021 - 2023', title: 'Full Stack Developer', company: 'StartupXYZ', description: 'Built scalable web applications from scratch' },
                { year: '2019 - 2021', title: 'Frontend Developer', company: 'DigitalAgency', description: 'Created responsive and interactive user interfaces' }
              ].map((item, index) => (
                <div key={index} className={`relative flex items-center ${index % 2 === 0 ? 'justify-start' : 'justify-end'}`}>
                  {/* Timeline Dot */}
                  <div className="absolute left-1/2 transform -translate-x-1/2 w-4 h-4 bg-accent rounded-full border-4 border-dark-bg"></div>
                  
                  {/* Content */}
                  <div className={`w-5/12 ${index % 2 === 0 ? 'pr-8 text-right' : 'pl-8 text-left'}`}>
                    <div className="bg-dark-card border border-dark-border rounded-lg p-6 hover-lift">
                      <div className="text-accent font-semibold mb-2">{item.year}</div>
                      <h4 className="text-lg font-semibold text-text-primary mb-2">{item.title}</h4>
                      <div className="text-accent/80 font-medium mb-2">{item.company}</div>
                      <p className="text-text-secondary">{item.description}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Skills;
